// Command wordfreq prints the 10 most frequent ASCII words read from standard input.
package main

import (
	"bufio"
	"fmt"
	"os"
)

// topN is the maximum number of words printed.
const topN = 10

func main() {
	counts, err := countWords(os.Stdin)
	if err != nil {
		fmt.Fprintln(os.Stderr, "wordfreq:", err)
		os.Exit(1)
	}

	w := bufio.NewWriter(os.Stdout)
	for _, e := range topWords(counts, topN) {
		fmt.Fprintf(w, "%d %s\n", e.count, e.word)
	}
	if err := w.Flush(); err != nil {
		fmt.Fprintln(os.Stderr, "wordfreq:", err)
		os.Exit(1)
	}
}

package main

import (
	"cmp"
	"errors"
	"io"
	"slices"
)

// entry is a word together with its number of occurrences.
type entry struct {
	word  string
	count int
}

// lowerTable maps ASCII letters to their lowercase form and every other byte
// to 0, which marks a separator.
var lowerTable = func() (t [256]byte) {
	for c := 'a'; c <= 'z'; c++ {
		t[c] = byte(c)
		t[c-'a'+'A'] = byte(c)
	}
	return t
}()

// countWords reads r to EOF and returns how often each lowercased word
// (maximal run of ASCII letters) occurs.
func countWords(r io.Reader) (map[string]int, error) {
	counts := make(map[string]int)
	buf := make([]byte, 64*1024)
	word := make([]byte, 0, 64) // current word; may span reads

	for {
		n, err := r.Read(buf)
		for _, b := range buf[:n] {
			if c := lowerTable[b]; c != 0 {
				word = append(word, c)
			} else if len(word) > 0 {
				counts[string(word)]++ // no allocation when the key exists
				word = word[:0]
			}
		}
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, err
		}
	}
	if len(word) > 0 {
		counts[string(word)]++
	}
	return counts, nil
}

// compareEntries orders entries by count descending, then by word ascending.
func compareEntries(a, b entry) int {
	if c := cmp.Compare(b.count, a.count); c != 0 {
		return c
	}
	return cmp.Compare(a.word, b.word)
}

// topWords returns up to n entries from counts, ordered by count descending
// and then by word ascending.
func topWords(counts map[string]int, n int) []entry {
	if n <= 0 {
		return nil
	}
	top := make([]entry, 0, n+1)
	for word, count := range counts {
		e := entry{word, count}
		if len(top) == n && compareEntries(e, top[n-1]) >= 0 {
			continue
		}
		i, _ := slices.BinarySearchFunc(top, e, compareEntries)
		top = slices.Insert(top, i, e)
		if len(top) > n {
			top = top[:n]
		}
	}
	return top
}

package main

import (
	"slices"
	"strings"
	"testing"
	"testing/iotest"
)

func TestTopWords(t *testing.T) {
	tests := []struct {
		name, in string
		want     []entry
	}{
		{"empty", "", nil},
		{"simple", "The cat and the hat.", []entry{{"the", 2}, {"and", 1}, {"cat", 1}, {"hat", 1}}},
		{"separators", "don't stop_me 4now, now-NOW\xff\xc3(", []entry{{"now", 3}, {"don", 1}, {"me", 1}, {"stop", 1}, {"t", 1}}},
		{"limit", "k j i h g f e d c b a a", []entry{{"a", 2}, {"b", 1}, {"c", 1}, {"d", 1}, {"e", 1}, {"f", 1}, {"g", 1}, {"h", 1}, {"i", 1}, {"j", 1}}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// OneByteReader forces words to span read boundaries.
			counts, err := countWords(iotest.OneByteReader(strings.NewReader(tt.in)))
			if err != nil {
				t.Fatal(err)
			}
			if got := topWords(counts, topN); !slices.Equal(got, tt.want) {
				t.Errorf("got %v, want %v", got, tt.want)
			}
		})
	}
}
